def record_completion(store, learner_id, lesson_id, request_id):
    if not isinstance(learner_id, str) or not isinstance(lesson_id, str):
        return {'status': 400, 'error': 'learner_id and lesson_id must be text'}
    if not request_id:
        return {'status': 400, 'error': 'request_id is required'}

    key = (learner_id, request_id)
    if key in store['requests']:
        return store['requests'][key]

    result = {'status': 201, 'lesson_id': lesson_id, 'state': 'completed'}
    store['requests'][key] = result
    store['completed'].add((learner_id, lesson_id))
    return result

