def record(store, learner_id, lesson_id, request_id):
    key=(learner_id,request_id)
    previous=store['requests'].get(key)
    if previous is not None:
        if previous['lesson_id']!=lesson_id:
            return {'status':409,'error':'request identity reused for different lesson'}
        return previous
    result={'status':201,'lesson_id':lesson_id}
    store['requests'][key]=result
    return result
